"""
title: Local Guardrail Safety Filter
author: VMware Private AI Services
version: 0.2.0
description: Sends each user message to a local guardrail/safety model before it reaches the chat model. Messages the guardrail flags as unsafe are blocked; safe messages are forwarded unchanged to whichever model is selected.
requirements: requests
"""

from typing import Any, Dict, List, Optional

import requests
from pydantic import BaseModel, Field


class Filter:
    class Valves(BaseModel):
        GUARDRAIL_API_BASE_URL: str = Field(
            default="http://open-webui-litellm-1:4000/v1",
            description="OpenAI-compatible base URL (include /v1) of the endpoint serving the local guardrail model.",
        )
        GUARDRAIL_API_KEY: str = Field(
            default="nokey",
            description="API key for the guardrail endpoint, if one is required.",
        )
        GUARDRAIL_MODEL: str = Field(
            default="llama-guard3",
            description="Name of the guardrail/safety model as registered on the guardrail endpoint.",
        )
        GUARDRAIL_SYSTEM_PROMPT: str = Field(
            default=(
                "You are a strict content-safety classifier. Classify ONLY the latest "
                'user message. Respond with exactly one word: "safe" if the message is '
                'appropriate, or "unsafe" if it contains harmful, dangerous, illegal, '
                "hateful, sexual, or otherwise policy-violating content. Do not answer "
                "the user's question or add any other text."
            ),
            description="System prompt prepended to the guardrail request, for use when the guardrail model is a general-purpose chat model rather than a purpose-built classifier (e.g. Llama Guard). Leave blank to send no system prompt.",
        )
        CHECK_FULL_CONVERSATION: bool = Field(
            default=False,
            description="If true, send the full message history to the guardrail model. If false, only the latest user message is checked.",
        )
        SAFE_KEYWORD: str = Field(
            default="safe",
            description="Case-insensitive token the guardrail model returns when a message is safe. Any other response is treated as unsafe.",
        )
        FAIL_CLOSED: bool = Field(
            default=True,
            description="If the guardrail check errors or times out: block the message (true) or let it through (false).",
        )
        BLOCK_MESSAGE: str = Field(
            default="Your message was flagged as unsafe by the guardrail model and was not sent to the assistant.",
            description="Message shown to the user when a request is blocked.",
        )
        TIMEOUT: float = Field(
            default=15.0,
            description="Timeout in seconds for the guardrail request.",
        )
        STATUS_INDICATOR: bool = Field(
            default=True,
            description="Emit chat status updates while the guardrail check runs.",
        )
        PRIORITY: int = Field(
            default=0,
            description="Execution priority relative to other active filters (lower runs first).",
        )
        DEBUG: bool = Field(
            default=False,
            description="Print debug information to the server console.",
        )

    def __init__(self):
        self.valves = self.Valves()

    def _log(self, message: str) -> None:
        if self.valves.DEBUG:
            print(f"[Guardrail Filter] {message}")

    def _flatten_content(self, content: Any) -> str:
        if isinstance(content, list):
            return "\n".join(
                part.get("text", "") for part in content if part.get("type") == "text"
            )
        return content or ""

    def _extract_messages(self, body: dict) -> List[Dict[str, str]]:
        messages = body.get("messages", [])
        plain_messages = [
            {"role": msg.get("role", "user"), "content": self._flatten_content(msg.get("content"))}
            for msg in messages
        ]
        if self.valves.CHECK_FULL_CONVERSATION:
            return plain_messages
        user_messages = [m for m in plain_messages if m["role"] == "user"]
        return [user_messages[-1]] if user_messages else []

    def _check_guardrail(self, messages: List[Dict[str, str]]) -> bool:
        if not messages:
            return True

        guardrail_messages = list(messages)
        if self.valves.GUARDRAIL_SYSTEM_PROMPT.strip():
            guardrail_messages = [
                {"role": "system", "content": self.valves.GUARDRAIL_SYSTEM_PROMPT}
            ] + guardrail_messages

        url = f"{self.valves.GUARDRAIL_API_BASE_URL.rstrip('/')}/chat/completions"
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.valves.GUARDRAIL_API_KEY}",
        }
        payload = {
            "model": self.valves.GUARDRAIL_MODEL,
            "messages": guardrail_messages,
            "temperature": 0,
            "max_tokens": 20,
        }

        response = requests.post(url, headers=headers, json=payload, timeout=self.valves.TIMEOUT)
        response.raise_for_status()
        result = response.json()
        verdict = result["choices"][0]["message"]["content"].strip()
        self._log(f"Guardrail verdict: {verdict!r}")
        return verdict.lower().startswith(self.valves.SAFE_KEYWORD.lower())

    async def inlet(
        self,
        body: dict,
        __user__: Optional[dict] = None,
        __event_emitter__=None,
    ) -> dict:
        messages = self._extract_messages(body)
        if not messages:
            return body

        if self.valves.STATUS_INDICATOR and __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "Checking message safety...", "done": False},
                }
            )

        try:
            is_safe = self._check_guardrail(messages)
        except Exception as e:
            self._log(f"Guardrail check failed: {e}")
            is_safe = not self.valves.FAIL_CLOSED

        if self.valves.STATUS_INDICATOR and __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "Message passed safety check"
                        if is_safe
                        else "Message blocked by safety check",
                        "done": True,
                    },
                }
            )

        if not is_safe:
            raise Exception(self.valves.BLOCK_MESSAGE)

        return body

    def outlet(self, body: dict, __user__: Optional[dict] = None) -> dict:
        return body
